INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63776665', 63776665, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'PENINGKATAN FUNGSI KEPELABUHANAN PUSAT', 'PENYUSUNAN STUDI DETAILED ENGINEERING DESIGN (DED) FASILITAS PELABUHAN LAUT TANJUNG BUTON PROVINSI RIAU', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 1650000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Pekerjaan ini meliputi penyusunan dokumen perencanaan teknis secara menyeluruh untuk fasilitas Pelabuhan Laut Tanjung Buton, yang mencakup kegiatan survei pendahuluan, pengumpulan data sekunder, survei lapangan, uji assessment terhadap struktur eksisting dan analisis struktur. Output berupa gambar desain, rencana kerja dan syarat-syarat (RKS), serta perhitungan estimasi biaya (Engineering Estimate) untuk keperluan rehabilitasi dan/atau pengembangan fasilitas Pelabuhan', 'Pekerjaan ini meliputi penyusunan dokumen perencanaan teknis yang harus diselesaikan dalam jangka waktu selama 210 hari kalender oleh penyedia jasa yang memiliki legalitas KBLI 71102 serta SBU kualifikasi menengah di bidang jasa desain rekayasa teknik sipil air. Tim pelaksana yang dipimpin oleh seorang Team Leader yang didukung oleh tenaga ahli struktur, geoteknik, kelautan, geodesi, Mekanikal Elektrikal, K3 konstruksi, dan cost estimator yang kompeten. Output akhir yang dihasilkan terdiri dari Laporan Pendahuluan, Laporan Antara, Konsep Laporan Akhir, serta Laporan Akhir yang dilengkapi dengan Album Gambar, Spesifikasi Teknis, dan dokumen Engineering Estimate', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1177215);
