INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63817807', 63817807, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Direktorat Jenderal Tata Ruang', 'Fasilitasi Penyelarasan Kebijakan Nasional pada Pulau Sumatera dan Kalimantan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 276593000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1', 'Kawasan Strategis Nasional (KSN) adalah wilayah yang penataan ruangnya diprioritaskan karena mempunyai pengaruh sangat penting secara nasional terhadap kedaulatan negara, pertahanan dan keamanan negara, ekonomi, sosial, budaya, dan/atau lingkungan, termasuk wilayah yang telah ditetapkan sebagai warisan dunia. Penataan ruang KSN dilakukan untuk mengembangkan, melestarikan, melindungi dan/atau mengkoordinasikan keterpaduan pembangunan nilai strategis kawasan dalam mendukung penataan ruang wilayah. Dalam Pasal 14 Undang-Undang Nomor 26 Tahun 2007 tentang Penataan Ruang, dinyatakan bahwa Rencana Tata Ruang (RTR) Pulau/Kepulauan dan KSN merupakan rencana rinci yang disusun sebagai perangkat operasional dari rencana umum tata ruang pada sistem nasional. Selanjutnya PP Nomor 13 Tahun 2017 tentang Perubahan Atas PP Nomor 26 Tahun 2008 tentang Rencana Tata Ruang Wilayah Nasional (RTRWN) menetapkan 76 (tujuh puluh enam) KSN. Dalam Lampiran X PP Nomor 13 Tahun 2017 tentang Perubahan Atas PP Nomor 26 Tahun 2008 tentang RTRWN, disebutkan bahwa KSN Kawasan Perbatasan Negara di Provinsi Aceh dan Provinsi Sumatera Utara, dan Kawasan Perbatasan Negara di Provinsi Riau dan Provinsi Kepulauan Riau merupakan KSN dari sudut kepentingan Pertahanan dan Keamanan dengan penekanan pada sisi pengembangan/peningkatan kualitas kawasan. Secara administratif Kawasan Perbatasan Negara di Provinsi Aceh dan Provinsi Sumatera Utara terletak di Provinsi Aceh dan Provinsi Sumatera Utara. Kawasan Perbatasan Negara di Provinsi Aceh dan Provinsi Sumatera Utara merupakan kawasan perbatasan negara yang ditetapkan dengan Peraturan Presiden Nomor 49 Tahun 2018 tentang Rencana Tata Ruang di Kawasan Perbatasan Negara di Provinsi Aceh dan Provinsi Sumatera Utara. Pada 2020 di Provinsi Riau dan Kepulauan Riau juga terdapat Rencana Tata Ruang di Kawasan Perbatasan Negara yang telah ditetapkan yaitu Peraturan Presiden Nomor 43 Tahun 2020 tentang Rencana Tata Ruang di Kawasan Perbatasan Negara di Provinsi Riau dan Provinsi Kepulauan Riau. Seiring dengan kompleksitas permasalahan tata ruang di KSN pada Pulau Sumatera dan Pulau Kalimantan, diperlukan upaya koordinasi dan penyelarasan kebijakan antara pemerintah pusat, daerah, dan pemangku kepentingan lainnya. Oleh karena itu, dalam rangka meningkatkan pemahaman stakeholder, memperkuat koordinasi, serta memfasilitasi penyelesaian isu pemanfaatan ruang, maka pada tahun anggaran 2026 Direktorat Perencanaan Tata Ruang Nasional - Direktorat Jenderal Tata Ruang, Kementerian Agraria dan Tata Ruang akan melaksanakan Fasilitasi Penyelarasan Kebijakan Nasional pada Pulau Sumatera dan Kalimantan.', 'Kegiatan ini menghasilkan dokumen laporan yang terdiri atas: Dokumen Diseminasi RTR Nasional pada Pulau Sumatera dan Kalimantan Laporan ini berisi rangkuman hasil kegiatan sosialisasi dan penyamaan persepsi mengenai RTR KSN dan RTR KPN kepada pemangku kepentingan. Berfungsi sebagai bukti pelaksanaan dan referensi bagi pemerintah pusat, daerah, serta stakeholder lainnya dalam memahami kebijakan tata ruang. Laporan ini diserahkan pada akhir masa pekerjaan dalam format "PDF" dan dicetak sebanyak 4 eksemplar pada bulan ke-12. Dokumen Inventarisasi Konflik dan Rekomendasi Solusi di dalam KSN dan KPN pada Pulau Sumatera dan Pulau Kalimantan Laporan ini memuat hasil identifikasi isu tata ruang dan konflik pemanfaatan ruang, termasuk penyebab dan dampaknya terhadap pemanfaatan KSN dan KPN. Memberikan rekomendasi teknis yang dapat digunakan sebagai masukan dalam peninjauan kembali dan revisi RTR KSN dan RTR KPN di masa mendatang. Laporan ini diserahkan pada akhir masa pekerjaan dalam format "PDF" dan dicetak sebanyak 4 eksemplar pada bulan ke-12.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1178038);
